const body = $json.body || {};
const url = body.url;
if (!url || typeof url !== 'string') {
  throw new Error('URL is required: body.url missing');
}
const m = url.match(/^https?:\/\/([^\/?#]+)/i);
if (!m) {
  throw new Error('Invalid URL format: ' + url);
}
let hostport = m[1];
let hostname = hostport.split(':')[0].toLowerCase().replace(/^\[|\]$/g, '');
const isIpv4 = /^\d+\.\d+\.\d+\.\d+$/.test(hostname);
let blocked = false;
if (isIpv4) {
  const ipToNum = (ip) => ip.split('.').reduce((a, o) => (a << 8) + parseInt(o, 10), 0) >>> 0;
  const n = ipToNum(hostname);
  const inRange = (a, b) => n >= ipToNum(a) && n <= ipToNum(b);
  blocked = inRange('10.0.0.0', '10.255.255.255') || inRange('172.16.0.0', '172.31.255.255') || inRange('192.168.0.0', '192.168.255.255') || inRange('127.0.0.0', '127.255.255.255') || inRange('169.254.0.0', '169.254.255.255') || n === 0;
} else {
  blocked = hostname === 'localhost' || hostname.endsWith('.local') || hostname.endsWith('.internal') || hostname.endsWith('.localhost') || hostname === '::1';
}
if (blocked) {
  throw new Error('SSRF blocked: private address (' + hostname + ')');
}
return [{ json: { url: url } }];

const html = String($json.body || $json.data || '');
const url = $json.url || ($('SSRF check').first() ? $('SSRF check').first().json.url : '');
const pick = (regexes) => {
  for (const re of regexes) {
    const m = html.match(re);
    if (m && m[1] !== undefined && m[1].trim() !== '') return m[1].trim();
  }
  return '';
};
const title = pick([/<title[^>]*>([^<]+)<\/title>/i]);
const meta_description = pick([
  /<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["'][^>]*>/i,
  /<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["'][^>]*>/i,
]);
const ogPick = (prop) => pick([
  new RegExp('<meta[^>]+property=["\']' + prop + '["\'][^>]+content=["\']([^"\']+)["\'][^>]*>', 'i'),
  new RegExp('<meta[^>]+content=["\']([^"\']+)["\'][^>]+property=["\']' + prop + '["\'][^>]*>', 'i'),
]);
const og = {
  title: ogPick('og:title'),
  description: ogPick('og:description'),
  image: ogPick('og:image'),
};
const h1m = html.match(/<h1[^>]*>([^<]+)<\/h1>/i);
const h1 = h1m ? h1m[1].trim() : '';
const socialDomains = [
  ['instagram.com', 'instagram'],
  ['t.me', 'telegram'],
  ['youtube.com', 'youtube'],
  ['vk.com', 'vk'],
  ['tiktok.com', 'tiktok'],
  ['x.com', 'x'],
  ['facebook.com', 'facebook'],
  ['rutube.ru', 'rutube'],
];
const socials = [];
const seen = new Set();
let origin = '';
try { origin = new URL(url).origin; } catch (e) { origin = ''; }
const hrefRe = /href=["']([^"']+)["']/gi;
let mm;
while ((mm = hrefRe.exec(html)) !== null) {
  let href = mm[1].trim();
  if (!href) continue;
  let full = href;
  if (href.startsWith('//')) full = 'https:' + href;
  else if (href.startsWith('/')) full = origin + href;
  for (const [domain, platform] of socialDomains) {
    if (full.indexOf(domain) !== -1) {
      if (!seen.has(full)) {
        seen.add(full);
        socials.push({ platform, url: full });
      }
      break;
    }
  }
  if (socials.length >= 10) break;
}
let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<nav[\s\S]*?<\/nav>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/\s+/g, ' ')
  .trim();
const text_excerpt = text.slice(0, 8000);
return [{ json: { url, title, meta_description, og, h1, socials, text_excerpt } }];
